// Refreshes src/hygiene-snapshot.ts, the vendored fallback of list hygiene's lists (the union of the sources in
// src/hygiene-sources.ts, less the allowlist), from the same sources and checks as the nightly sync.
// Usage, from api/: node --import tsx scripts/update-hygiene-snapshot.ts
// Commit the regenerated file. Nightmail uses it only until the nightly sync has stored lists, or while every sync fails.
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { buildLists, fetchSource, SOURCES } from '../src/hygiene-sources.js';

const fetched = [];
for (const source of SOURCES) {
  const got = await fetchSource(source, null);
  console.log(`${source.name} (${source.license}): ${got.entries.length} entries`);
  fetched.push(got);
}
const built = buildLists(fetched);
const { disposable, ...rest } = built;
const out = `// Generated by scripts/update-hygiene-snapshot.ts: do not edit by hand. The fallback list hygiene uses until the nightly sync
// has stored lists of its own (src/list-hygiene.ts). Sources and licenses: docs/list-hygiene.md.
import type { BuiltLists } from './hygiene-sources.js';
const meta = ${JSON.stringify(rest)};
export const HYGIENE_SNAPSHOT: BuiltLists = { ...meta, disposable: \`
${disposable}\`.slice(1) };
`;
writeFileSync(fileURLToPath(new URL('../src/hygiene-snapshot.ts', import.meta.url)), out);
console.log(`Wrote ${disposable.split('\n').length} disposable domains, ${built.providers.length} providers, ${built.roles.length} roles, version ${built.version}`);
